package com.aliothmoon.maafw.once;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.file.*;
public class NativeUiBoundHelperWiringTest {
 String source()throws Exception{return Files.readString(Path.of(System.getProperty("staging.root",".."),"app/src/main/java/com/aliothmoon/maafw/once/NativeUiStructureHelper.java"));}
 @Test public void exactModeOnly(){assertTrue(NativeUiStructureHelper.validReadyArguments(new String[]{"n","d","BOUND_POINTS_V53"}));assertFalse(NativeUiStructureHelper.validReadyArguments(new String[]{"n","d","BOUND_POINTS_V53 "}));assertFalse(NativeUiStructureHelper.validReadyArguments(new String[]{"n","d","BOUND_POINTS_V53","extra"}));}
 @Test public void actualNodeRelationshipAndGeometry()throws Exception{String s=source();assertTrue(s.contains("if(boundMode){Rect originalBounds=new Rect();node.getBoundsInScreen(originalBounds)"));assertTrue(s.contains("new NativeUiBoundPointsParser.Node(current.index(),current.parent(),visible,true"));assertTrue(s.contains("node.getViewIdResourceName(),text,description,originalBounds.left,originalBounds.top,originalBounds.right,originalBounds.bottom"));assertTrue(s.contains("boundRecords.clear()"));}
 @Test public void scopedCapabilityAndExactReadback()throws Exception{String s=source();assertTrue(s.contains("boundMode ? AccessibilityServiceInfo.FLAG_REPORT_VIEW_IDS : 0"));assertTrue(s.contains("readback.flags != requiredFlags"));assertTrue(s.contains("UiAutomation.FLAG_DONT_SUPPRESS_ACCESSIBILITY_SERVICES"));}
 @Test public void boundParserExclusiveAndDiagnosticModesUnknown()throws Exception{String s=source();assertTrue(s.contains("if(!fieldMode){if(!readyMode||!diagnostics.blocked())"));assertTrue(s.contains("boundMode?NativeUiBoundPointsParser.parse(boundRecords):formatMode?NativeUiStructureV50Parser.parse(records):NativeUiStructureParser.parse(records)"));assertTrue(s.contains("if(locatedMode)fieldMode=true"));assertTrue(s.contains("fieldMode?fieldDiagnostics.result():null,boundMode"));}
 @Test public void sameBoundedSingleReadAndNoInput()throws Exception{String s=source();assertTrue(s.contains("automation.waitForIdle(500,3000)"));assertTrue(s.contains("scheduled + count > 512"));assertTrue(s.contains("current.depth() >= 32"));assertTrue(s.contains("32768"));assertEquals(s.indexOf("automation.getRootInActiveWindow()"),s.lastIndexOf("automation.getRootInActiveWindow()"));for(String forbidden:new String[]{"performAction(","ACTION_SHOW_ON_SCREEN","ACTION_CLICK","takeScreenshot","getWindows(","dumpWindowHierarchy"})assertFalse(forbidden,s.contains(forbidden));}
}
